class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        a, b = energyDrinkA[0], energyDrinkB[0]
        pa = pb = 0
        for i in range(1, len(energyDrinkA)):
            na = energyDrinkA[i] + max(a, pb)
            nb = energyDrinkB[i] + max(b, pa)
            pa, pb = a, b
            a, b = na, nb
        return max(a, b)

