        da[0] = A[0]; db[0] = B[0];
        for (int i = 1; i < n; ++i) {
            da[i] = A[i] + max(da[i-1], i >= 2 ? db[i-2] : 0LL);
            db[i] = B[i] + max(db[i-1], i >= 2 ? da[i-2] : 0LL);
        }
        return max(da[n-1], db[n-1]);
    }
};

